<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import { ruleSourceDocuments, type RuleSourceBlock, type RuleSourceSection } from '../data/rulesSource'
import { coreAbilities } from '../data/coreAbilities'
import diceStrip from '../assets/rules/brambleheart-dice-strip.webp'
import { useSettings } from '../state/settings'
import { formatMeasurementText } from '../rules/measurements'

const route=useRoute()
const router=useRouter()
const {measurement}=useSettings()
const ATTRIBUTE_HEADINGS=new Set(['ATTRIBUTES','RANKS & MODIFIERS','SKILLS','SKILL TREES','EXPANDED & RESTRICTED'])
const sourceKeys=computed(()=>[...Object.keys(ruleSourceDocuments),'fundamentals-attributes','fundamentals-abilities'].filter((value,index,array)=>array.indexOf(value)===index).sort((a,b)=>a.localeCompare(b)))
const requestedKey=computed(()=>String(route.params.slug||''))
const activeKey=computed(()=>sourceKeys.value.includes(requestedKey.value)?requestedKey.value:(sourceKeys.value.includes('fundamentals')?'fundamentals':sourceKeys.value[0]||''))
const sourceKey=computed(()=>['fundamentals-attributes','fundamentals-abilities'].includes(activeKey.value)?'fundamentals':activeKey.value)
const documentSource=computed(()=>ruleSourceDocuments[sourceKey.value])
const title=computed(()=>activeKey.value==='fundamentals-attributes'?'Attributes & Skills':activeKey.value==='fundamentals-abilities'?'Abilities':activeKey.value.split('-').filter(Boolean).map(word=>word[0]?.toUpperCase()+word.slice(1)).join(' '))
const isFundamentals=computed(()=>activeKey.value==='fundamentals')
const isAttributesPage=computed(()=>activeKey.value==='fundamentals-attributes')
const isAbilitiesPage=computed(()=>activeKey.value==='fundamentals-abilities')
const abilityCostKeywords=new Set(['Core','Root','Move','Combat','Reactive','Instinct','Passive','Touch','Shoot','Magic'])
function canonicalAbilityType(value:string){const key=String(value||'').trim().toLowerCase();if(key==='reaction')return'Reactive';if(key==='movement')return'Move';if(key==='melee')return'Touch';return String(value||'').trim().replace(/^./,letter=>letter.toUpperCase())}
function abilityTypeClass(value:string){return`type-${canonicalAbilityType(value).toLowerCase().replace(/[^a-z0-9]+/g,'-')}`}
const coreFamilyPriority=['Instinct','Move','Touch','Shoot','Magic','Passive']
function coreAbilityFamily(keywords:string[]){return coreFamilyPriority.find(family=>keywords.map(canonicalAbilityType).includes(family))||'Core'}
function coreAbilityCardClass(keywords:string[]){return abilityTypeClass(coreAbilityFamily(keywords))}

function splitTargets(section:RuleSourceSection){
  const regular:RuleSourceBlock[]=[]
  const targets:RuleSourceBlock[]=[]
  let targetMode=false
  for(const block of section.blocks){
    if(block.type==='paragraph'&&/ACTIVE\s*&\s*PASSIVE TARGETS/i.test(block.text)){
      targetMode=true
      targets.push({...block,text:block.text.replace(/^ACTIVE\s*&\s*PASSIVE TARGETS\s*/i,'').trim()})
      continue
    }
    ;(targetMode?targets:regular).push(block)
  }
  return{regular,targets}
}
function sectionByHeading(sections:RuleSourceSection[],heading:string){return sections.find(section=>section.heading.toUpperCase()===heading)}
function isSecondaryStatsParagraph(block:RuleSourceBlock){return block.type==='paragraph'&&/^SECONDARY STATS:/i.test(block.text.trim())}
const bodySections=computed<RuleSourceSection[]>(()=>{
  const sections=(documentSource.value?.sections||[]).filter(section=>section.heading.toLowerCase()!=='overview')
  if(isAbilitiesPage.value)return[]
  if(isAttributesPage.value){
    const attributes=sectionByHeading(sections,'ATTRIBUTES')
    const ranks=sectionByHeading(sections,'RANKS & MODIFIERS')
    const skills=sectionByHeading(sections,'SKILLS')
    const trees=sectionByHeading(sections,'SKILL TREES')
    const expanded=sectionByHeading(sections,'EXPANDED & RESTRICTED')
    const out:RuleSourceSection[]=[]
    if(attributes)out.push({...attributes,blocks:attributes.blocks.filter(block=>!isSecondaryStatsParagraph(block))})
    if(ranks)out.push(ranks)
    const treeTables=(expanded?.blocks||[]).filter(block=>block.type==='table')
    if(skills||trees||treeTables.length)out.push({heading:'SKILLS',blocks:[...(skills?.blocks||[]),...(trees?.blocks||[]),...treeTables]})
    if(expanded)out.push({heading:'EXPANDED & RESTRICTED',blocks:expanded.blocks.filter(block=>block.type!=='table')})
    return out
  }
  if(!isFundamentals.value)return sections
  const out:RuleSourceSection[]=[]
  for(const section of sections){
    if(ATTRIBUTE_HEADINGS.has(section.heading.toUpperCase()))continue
    if(section.heading.toUpperCase()==='EDGED & WEIGHTED ROLLS'){
      const split=splitTargets(section)
      out.push({...section,blocks:split.regular})
      if(split.targets.length)out.push({heading:'ACTIVE & PASSIVE TARGETS',blocks:split.targets})
      continue
    }
    out.push(section)
  }
  return out
})

const bannerModules=import.meta.glob('../assets/rule-banners/*.{png,PNG,jpg,JPG,jpeg,JPEG,webp,WEBP}',{eager:true,query:'?url',import:'default'}) as Record<string,string>
function key(value:string){return value.replace(/[^a-z0-9]+/gi,'').toLowerCase()}
function bannerStem(path:string){return(path.split('/').pop()||'').replace(/\.[^.]+$/,'').replace(/^banner[-_ ]*/i,'')}
const banner=computed(()=>{const wanted=key(sourceKey.value);return Object.entries(bannerModules).find(([path])=>{const stem=key(bannerStem(path));return stem===wanted||stem.endsWith(wanted)||wanted.endsWith(stem)})?.[1]||''})
function sectionId(value:string,index:number){return`preview-${index}-${value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'section'}`}
function selectSource(event:Event){const value=(event.target as HTMLSelectElement).value;if(value)void router.replace(`/rules/layout-preview/${value}`)}
const targetExamples:Record<string,string>={Easy:'Routine task under light pressure',Medium:'Standard challenge with meaningful risk',Difficult:'Demanding task requiring strong skill',Hard:'Severe challenge under poor conditions','Very Hard':'Extreme feat with little margin'}
function tableRows(section:RuleSourceSection,block:RuleSourceBlock){
  if(block.type!=='table')return[]
  if(section.heading!=='ACTIVE & PASSIVE TARGETS')return block.rows
  return block.rows.map((row,index)=>index===0?[...row,'Example']:[...row,targetExamples[row[0]||'']||''])
}
function displayText(text:string){return formatMeasurementText(text,measurement.value)}
function displayParagraph(section:RuleSourceSection,text:string){
  let value=displayText(text)
  if(section.heading==='HALF-STEP ROLLS'){
    if(/divide the natural \(unmodified\) dice result by two/i.test(value))return'For a half-step roll, roll 1d10 and read the die by its result band. Do not divide the die result.'
    if(/The resulting value will determine your final total/i.test(value))return'A natural d10 result of 1–5 gives a half-step result of 1. A natural d10 result of 6–10 gives a half-step result of 2.'
    if(/required to roll \[1d10\/2\+1\]/i.test(value))return'The notation [1d10/2+1] means: roll the d10, convert it to its half-step result (1 or 2), then add the listed +1 condition.'
  }
  return value
}
function displayHeading(value:string){return value.toUpperCase()==='FORTUNE & MISFORTUNE RESULTS'?'FORTUNE & MISFORTUNE':value}
function isFormulaParagraph(section:RuleSourceSection,block:RuleSourceBlock){return section.heading==='THE CORE ROLL'&&block.type==='paragraph'&&/\(3d10\)\s*\+\s*stat/i.test(block.text)}
function isHalfStepFormula(block:RuleSourceBlock){return block.type==='paragraph'&&/^\(1d10\/2\)$/i.test(block.text.trim())}
function showConditionsGraphic(section:RuleSourceSection,blockIndex:number){return section.heading==='CONDITIONS'&&blockIndex===0}
function showFortuneGraphic(section:RuleSourceSection){return section.heading==='FORTUNE & MISFORTUNE RESULTS'}
function showHalfStepExample(section:RuleSourceSection){return section.heading==='HALF-STEP ROLLS'}
function showEdgedWeightedGraphic(section:RuleSourceSection){return section.heading==='EDGED & WEIGHTED ROLLS'}
function isTargetSection(section:RuleSourceSection){return section.heading==='ACTIVE & PASSIVE TARGETS'}
function showSecondaryStatsGraphic(section:RuleSourceSection){return isAttributesPage.value&&section.heading==='ATTRIBUTES'}
function skillTreeName(block:RuleSourceBlock){if(block.type!=='table'||block.rows.length<2)return'';const row=block.rows[1];return row.length===1&&/Skill Tree$/i.test(row[0])?displayText(row[0]):''}
function skillTreeTone(name:string){return name.toLowerCase().split(' ')[0]||'skill'}
function skillTreeRows(block:RuleSourceBlock){return block.type==='table'?block.rows.slice(2).filter(row=>row.some(cell=>String(cell).trim())):[]}
const secondaryBreakdown=[
  {name:'Agility',short:'AGI',rank:'Accuracy',modifier:'Aim',extra:'Speed = 2 + AGI modifier'},
  {name:'Might',short:'MIG',rank:'Fury',modifier:'Brawl',extra:''},
  {name:'Hide',short:'HID',rank:'Guts',modifier:'Ward',extra:''},
  {name:'Lore',short:'LOR',rank:'Power',modifier:'Control',extra:''},
  {name:'Bravery',short:'BRY',rank:'Heart',modifier:'Spirit',extra:''},
]
const previousPage=computed(()=>isAttributesPage.value?{label:'Fundamentals',path:'/rules/layout-preview/fundamentals'}:isAbilitiesPage.value?{label:'Attributes & Skills',path:'/rules/layout-preview/fundamentals-attributes'}:null)
const nextPage=computed(()=>isFundamentals.value?{label:'Attributes & Skills',path:'/rules/layout-preview/fundamentals-attributes'}:isAttributesPage.value?{label:'Abilities',path:'/rules/layout-preview/fundamentals-abilities'}:null)
</script>

<template>
  <main class="page rule-layout-preview-page">
    <AppHeader compact back-to="/rules" back-label="Back to Rules" prefer-back-to />

    <div class="rule-layout-preview-notice card-surface"><strong>RULE PAGE LAYOUT PREVIEW — TEST PAGE</strong><span>This route is isolated from the existing Rule Reader. It does not replace production rule pages.</span></div>

    <label class="field-label rule-layout-preview-picker">Preview Source<select class="field-control" :value="activeKey" @change="selectSource"><option v-for="source in sourceKeys" :key="source" :value="source">{{ source }}</option></select></label>

    <article v-if="documentSource" class="rule-layout-preview-shell">
      <header class="rule-layout-preview-hero card-surface" :class="{withBanner:banner}" :style="banner?{backgroundImage:`linear-gradient(rgba(20,17,14,.22),rgba(20,17,14,.58)),url(${banner})`}:undefined"><p class="eyebrow">RULES LAYOUT TEST</p><h1>{{ title }}</h1></header>

      <section class="rule-layout-preview-body card-surface">
        <section v-if="isAbilitiesPage" class="abilities-preview-stack">
          <article id="preview-abilities-what" class="rule-layout-preview-section"><h2>WHAT ARE ABILITIES?</h2><p>Abilities are the rules a character uses to act during an encounter. A normal round gives every character one CORE Instinct, one CORE Move, and one CORE Combat opportunity. Reactive abilities answer their own printed triggers.</p><div class="ability-economy-graphic"><div class="economy-node type-instinct"><small>ROUND TIMING</small><strong>CORE · INSTINCT</strong><span class="ability-cost-pill type-instinct">INSTINCT</span></div><div class="economy-node type-move"><small>ON TURN</small><strong>CORE · MOVE</strong><span class="ability-cost-pill type-move">MOVE</span></div><div class="economy-node type-combat"><small>ON TURN</small><strong>CORE · COMBAT</strong><span class="ability-cost-pill type-combat">COMBAT</span></div></div></article>
          <article id="preview-abilities-how" class="rule-layout-preview-section"><h2>HOW ABILITIES WORK</h2><p>CORE abilities are the shared baseline. Talents, Traits, Spells, and equipment can modify that baseline or trigger from what happens.</p><div class="ability-example-flow ordered-flow three-panel"><div class="mini-rule-node core"><strong>Choose an ability</strong><small>Spend the matching CORE opportunity.</small><span class="ability-cost-pill type-core">CORE</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node modifier"><strong>Apply interactions</strong><small>Talent · Spell · Trait · Equipment</small><span class="ability-cost-pill type-reactive">INTERACTION</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node result"><strong>Resolve</strong><small>TO HIT, Save, Effect, Damage, Duration.</small><span class="ability-cost-pill type-passive">RESULT</span></div></div></article>
          <article id="preview-abilities-example" class="rule-layout-preview-section"><h2>ABILITY EXAMPLE</h2><p>One CORE Combat opportunity may be modified by another rule without creating a second CORE Combat opportunity.</p><div class="ability-example-flow ordered-flow three-panel combat-example"><div class="mini-rule-node magic"><strong>Arcane Command</strong><small>Selu casts Ballad of the Courageous.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-core">CORE</span><span class="ability-cost-pill type-combat">COMBAT</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node spell"><strong>Ballad resolves</strong><small>The spell grants its listed Enhance.</small><span class="ability-cost-pill type-magic">ENHANCE</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node talent"><strong>Hearth Touch</strong><small>Because an Enhance was granted, Hearth Touch resolves from its trigger.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-passive">PASSIVE</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div></div></article>
          <article id="preview-abilities-reactive" class="rule-layout-preview-section"><h2>REACTIVE ABILITIES</h2><p>A Reactive ability resolves when its printed triggering event happens, not after the triggering ability has completely finished. Resolve the Reactive rule at that interruption point, then continue whatever remains legal from the triggering ability or turn.</p><div class="ability-example-flow ordered-flow three-panel reactive-example"><div class="mini-rule-node enemy"><strong>Enemy ability begins</strong><small>The enemy reaches the event named by Selu’s Reactive Trigger.</small><span class="ability-cost-pill type-combat">ENEMY ABILITY</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node reactive"><strong>Reactive resolves now</strong><small>Pause at the trigger, pay any cost, and resolve the Reactive ability immediately.</small><span class="ability-cost-pill type-reactive">REACTIVE</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node result"><strong>Enemy continues</strong><small>Resume and finish the remaining legal parts of the ability or turn.</small><span class="ability-cost-pill type-passive">CONTINUE</span></div></div></article>
          <article id="preview-abilities-core" class="rule-layout-preview-section"><h2>BASIC CORE ABILITIES</h2><p>Open the reference below when you need the complete shared list. These cards use the same Core Ability data as the rest of the app.</p><details class="core-ability-catalog" open><summary>Complete Core Ability List <span>{{ coreAbilities.length }} abilities</span></summary><div class="preview-core-ability-grid"><article v-for="ability in coreAbilities" :key="ability.name" class="trait-card preview-core-ability-card" :class="ability.keywords.map(keyword=>`type-${canonicalAbilityType(keyword).toLowerCase()}`)"><div class="trait-card-head"><div><h3>{{ ability.name }}</h3><small>Core Ability · Core</small></div><div><span v-if="ability.cost" class="mana-badge">{{ ability.cost }}</span></div></div><p class="rule-flavor"><em>{{ ability.flavor }}</em></p><div class="rule-breakdown-grid"><div v-for="field in ability.fields" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in ability.keywords" :key="keyword" :class="abilityCostKeywords.has(canonicalAbilityType(keyword))?['ability-cost-pill',abilityTypeClass(keyword)]:'keyword-pill'">{{ canonicalAbilityType(keyword) }}</span></div></article></div></details></article>
        </section>
        <article v-for="(section,index) in bodySections" :id="sectionId(section.heading,index)" :key="`${section.heading}-${index}`" class="rule-layout-preview-section">
          <h2>{{ displayHeading(section.heading) }}</h2>
          <figure v-if="isFundamentals && section.heading==='THE CORE ROLL'" class="rule-layout-preview-dice"><img :src="diceStrip" alt="Illustrated polyhedral dice" /></figure>
          <template v-if="showSecondaryStatsGraphic(section)">
            <p class="secondary-stats-summary">Secondary stats are derived values tied to an Attribute. A secondary stat uses either that Attribute’s Rank or its modifier; its rule tells you which value applies.</p>
            <div class="attribute-breakdown-graphic" aria-label="Attribute to secondary-stat breakdown">
              <article v-for="item in secondaryBreakdown" :key="item.short" class="attribute-breakdown-card"><header><strong>{{ item.name }}</strong><small>{{ item.short }}</small></header><div><span>Rank</span><b>→</b><strong>{{ item.rank }}</strong></div><div><span>Modifier</span><b>→</b><strong>{{ item.modifier }}</strong></div><small v-if="item.extra">{{ item.extra }}</small></article>
            </div>
          </template>

          <template v-for="(block,blockIndex) in section.blocks" :key="blockIndex">
            <div v-if="isFormulaParagraph(section,block)" class="core-roll-formula">3d10 + Stat + Conditions</div>
            <p v-else-if="block.type==='paragraph' && !isHalfStepFormula(block)">{{ displayParagraph(section,block.text) }}</p>
            <div v-else-if="block.type==='paragraph'" class="half-step-rule-graphic" aria-label="Half-step result bands"><div class="half-step-roll-node"><small>Roll one die</small><strong>d10</strong></div><span class="half-step-arrow">↓</span><div class="half-step-band-grid"><div class="half-step-band-node"><small>Natural result</small><strong>1–5</strong><b>→ 1</b></div><div class="half-step-band-node"><small>Natural result</small><strong>6–10</strong><b>→ 2</b></div></div><small class="half-step-read-note">Read the natural die result by band. Do not divide the number shown on the die.</small></div>
            <article v-else-if="skillTreeName(block)" class="skill-tree-card" :class="`skill-tree-${skillTreeTone(skillTreeName(block))}`"><header><strong>{{ skillTreeName(block) }}</strong><small>Skill · Description · Example</small></header><div class="skill-tree-list"><div v-for="(row,rowIndex) in skillTreeRows(block)" :key="rowIndex"><strong>{{ displayText(row[0]||'') }}</strong><span>{{ displayText(row[1]||'') }}</span><small>{{ displayText(row[2]||'') }}</small></div></div></article>
            <div v-else class="rule-layout-preview-table-wrap" :class="{'target-example-table':isTargetSection(section)}"><table><tbody><tr v-for="(row,rowIndex) in tableRows(section,block)" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div>

            <div v-if="showConditionsGraphic(section,blockIndex)" class="condition-process" aria-label="Conditions example"><div class="condition-node bonus"><small>Condition</small><strong>High Ground</strong><b>+1</b></div><span>+</span><div class="condition-node bonus"><small>Condition</small><strong>Fortune</strong><b>+2</b></div><span>+</span><div class="condition-node penalty"><small>Condition</small><strong>Obscured</strong><b>−1</b></div><span>=</span><div class="condition-node total"><small>Total Modifier</small><strong>Conditions</strong><b>+2</b></div></div>
          </template>

          <div v-if="showEdgedWeightedGraphic(section)" class="edge-weight-example-grid" aria-label="Edged and weighted roll examples"><article><h3>Edged Roll</h3><div class="example-dice edge-dice"><span class="dropped">2</span><span>5</span><span>7</span><span>9</span></div><small>Drop the lowest die.</small><strong>5 + 7 + 9 = 21</strong></article><article><h3>Weighted Roll</h3><div class="example-dice edge-dice"><span>2</span><span>5</span><span>7</span><span class="dropped">9</span></div><small>Drop the highest die.</small><strong>2 + 5 + 7 = 14</strong></article></div>

          <div v-if="showFortuneGraphic(section)" class="fortune-example-grid"><article><h3>Fortune Example</h3><div class="example-dice"><span class="fortune">9</span><span class="fortune">8</span><span>5</span></div><strong>2 Fortune → +2 Conditions</strong></article><article><h3>Misfortune Example</h3><div class="example-dice"><span class="misfortune">1</span><span class="misfortune">2</span><span>6</span></div><strong>2 Misfortune → −2 Conditions</strong></article></div>
          <article v-if="showHalfStepExample(section)" class="talent-half-step-example"><span class="eyebrow">CURRENT TALENT EXAMPLE</span><h3>Threadseer</h3><p><strong>Cooldown:</strong> [1d10/2+1]. Roll the d10, convert 1–5 to a half-step result of 1 or 6–10 to a result of 2, then add the listed +1 condition.</p><div class="half-step-math" aria-label="Half-step Threadseer example"><span class="math-die"><small>d10</small><b>8</b></span><span class="math-operator">→</span><span class="math-result"><small>6–10</small><b>2</b></span><span class="math-operator">+1</span><span class="math-result final"><small>Final</small><b>3</b></span></div></article>
        </article>
      </section>

      <nav v-if="previousPage||nextPage" class="rule-preview-page-nav card-surface" aria-label="Fundamentals preview pages"><RouterLink v-if="previousPage" class="secondary-button" :to="previousPage.path">← {{ previousPage.label }}</RouterLink><span></span><RouterLink v-if="nextPage" class="secondary-button" :to="nextPage.path">{{ nextPage.label }} →</RouterLink></nav>

      <nav v-if="bodySections.length||isAbilitiesPage" class="rule-layout-preview-contents card-surface" aria-label="Preview page contents"><h2>Contents</h2><div v-if="isAbilitiesPage" class="rule-layout-preview-links"><a href="#preview-abilities-what">Ability Economy</a><a href="#preview-abilities-how">How Abilities Work</a><a href="#preview-abilities-instinct">Instinct</a><a href="#preview-abilities-move">Move</a><a href="#preview-abilities-combat">Combat + Talent</a><a href="#preview-abilities-reactive">Reactive & Passive</a><a href="#preview-abilities-core">Core Reference</a></div><div v-else class="rule-layout-preview-links"><a v-for="(section,index) in bodySections" :key="`${section.heading}-${index}`" :href="`#${sectionId(section.heading,index)}`">{{ displayHeading(section.heading) }}</a></div></nav>
    </article>
  </main>
</template>

<style scoped>
