 var(--line)}.core-ability-catalog .preview-core-ability-grid{padding:12px}.rule-example-copy{padding:9px 11px;border-left:5px solid var(--section-tone);border-right:5px solid var(--section-tone);border-radius:8px;background:color-mix(in srgb,var(--section-tone) 8%,var(--paper-2))}
